// entities/vectorindex/common/config.go lines 95-110
func OptionalStringFromMap(in map[string]interface{}, name string,
	setFn func(v string),
) error {
	value, ok := in[name]
	if !ok {
		return nil
	}

	asString, ok := value.(string)
	if !ok {
		return nil  // BUG: When value is null, this returns nil WITHOUT calling setFn, leaving default value intact
	}

	setFn(asString)
	return nil
}

